-- 2026 timesheets imported from the Staff Record Keeping sheet (Timesheet tab), replacing the
-- partial rows previously entered for Nitz, Reland and Ronnie. Purple = Holiday, red = Sick,
-- L = Unpaid Leave. Jan-Oct were paid through the sheet, so they're marked Paid; 1-13 Nov are
-- Approved for the November payroll. Geo: November working days only (fixed monthly salary).
DELETE FROM timesheets
WHERE date >= DATE '2026-01-01'
  AND employee_id IN ('ff481ff3-54d3-4b11-88f1-d7a7b9079a4a', 'b403b39a-07df-4748-bc64-3d2c997930f0', '3ac30508-e442-46c3-b7fa-b134e32241ea');
DELETE FROM timesheets
WHERE date >= DATE '2026-11-01' AND employee_id = '43ae55f6-fe46-46d3-8652-b1424dc03d52';

-- Each entry: employee (1 Nitz, 2 Reland, 3 Ronnie, 4 Geo), MMDD, day type code, then optional /overtime hours/day fraction.
WITH raw AS (
  SELECT unnest(string_to_array('10102R/1/1 10103R 10104R 10105R 10106R 10107R 10108R 10110R 10111R 10112R 10113R 10114R 10115R 10116R 10117R 10118R 10119R 10120H 10121H 10122H 10201H 10202H 10203H 10204H 10205H 10206H 10207H 10208H 10209H 10210H 10211H 10212H 10213H 10214H 10215H 10217SH/0.75/1 10218R 10219R 10220R 10221R 10222R 10223R 10224R 10225R/2/1 10226S 10227S 10228R 10301R/1/1 10302R 10303R 10304R 10305R/1/1 10307R 10308R 10309R 10310R 10311R 10312R 10314R 10315R 10316R 10317R 10318R 10319R 10320RH 10321R 10323R 10324R 10325R 10326R 10327R 10329R 10330R 10401R 10402RH 10403RH 10404SH 10406R 10407R 10408R 10409RH 10410R 10411R 10413S 10414S 10415S 10416S 10417S 10425R 10426R 10427R 10428R 10429R 10430R 10501RH 10502R 10503R 10505R/1/1 10506R 10507R 10508R 10509U 10510U 10511U 10512U 10513U 10514U 10515U 10516U 10517U 10518U 10519U 10520R 10521R 10522R 10523R/1/1 10524R 10526R 10527RH 10528R 10529R 10530R 10531R 10601R 10603R 10604R 10605R 10606R 10607R 10608R 10610R 10611R 10612RH 10613R 10614R 10615R 10616R 10619R 10620R 10621R 10622R 10623R 10624R 10625R 10628R 10629R 10630R 10701R 10702R 10703R 10704R 10705R 10707R 10708R 10709R 10710R 10711R 10714R 10715R 10716R 10717R 10718R 10720R 10721R 10722R 10723R 10724R 10725R 10727R 10728R 10729R 10730R 10731R 10801R 10802R 10804R 10805R 10806R 10807R 10809U 10810U 10811U 10812U 10813U 10814U 10815U 10816U 10817U 10818U 10819U 10820U 10821U 10822U 10823U 10824U 10825U 10826R 10827R 10828R 10829R 10830R 10831RH 10901R 10902R 10903R 10905R 10906R 10907R 10908R 10909R 10910R 10912R 10913R 10914R 10915R 10916R 10917R 10919R 10920R 10921R 10922R 10923R 10924R 10926R 10927R 10928R 10929R 10930R 11001R 11002R 11003R 11005R 11006R 11007R 11008R 11009R 11010R 11012R 11013R 11014R 11015R 11017R/0/0.625 11018R 11019R 11020R 11022R 11023R 11024U 11025U 11026U 11027U 11028U 11029U 11030U 11031U 11101U 11102U 11103U 11104U 11105U 11106R 11107R 11108R/1/1 11109R 11110R 11111R 11112R 11113R 20102R/1/1 20103R 20104R 20105R 20107R 20108R 20109R 20110R 20111R 20112R 20113R 20114R 20115R 20117R 20118R 20119R 20120R 20121R 20122R 20124R/1/1 20125R 20126R 20128R 20129R 20130R/1/1 20131R/1/1 20201R 20202R 20203H 20204H 20205H 20206R 20207R 20208R/1/1 20209S 20210S 20211R 20212R 20213R 20214R 20215R 20216R 20217SH/0.75/1 20219H 20220H 20221R 20222R 20223R 20224R 20226R/1/1 20227R 20228R 20301R/1/1 20302R 20303R 20304R 20306R 20307R/1/1 20308R 20309R/2/1 20311R 20312R/1/1 20313R 20314R 20315R 20316R 20317R 20318R 20320RH 20321R 20322R 20323R 20324R 20326R 20327R 20328R 20329R 20330R 20402R 20403RH 20404SH 20405R 20406R 20407R 20408R 20409R 20411R 20412R 20413R 20414R 20415R 20419R 20420R/1/1 20421R/1/1 20422R 20423R 20424R 20425R 20426R 20427S 20428R 20429R 20430R 20501RH 20502R 20504R 20505R 20506R 20507H 20508R 20509R 20510R 20511H 20512H 20513R 20514R/1/1 20515R 20516H 20517R 20518R/0.5/1 20519R 20520R 20521H 20522H 20523H 20524R 20525R 20526R 20527RH 20528R 20529R 20530R 20531R 20602R 20603R 20604R 20606R 20607R 20610R 20611R 20612RH 20613R 20614R 20615R 20616R 20617R 20620R 20621R 20622R 20625R 20626R 20627H 20628H 20629H 20630R 20701R 20703R 20704R 20705R 20706R 20707R 20709R 20710R 20711H 20712H 20713H 20714R 20715R 20716R 20717R 20718R 20719R 20722R 20723R/1/1 20724R 20725R 20726R 20727R 20728R 20730R 20731R 20801R 20802R 20803R 20804R 20806R 20807R/1/1 20808R 20809R 20810R 20812R 20813R/0.5/1 20814R 20815R 20816R 20817R 20818R 20820R 20821RH 20822R 20823R/1/1 20825R 20826R 20827R 20828U 20829U 20830U 20831U 20901S 20902S 20903S 20904S 20905U 20906U 20907U 20908U 20909U 20910U 20911U 20912U 20913U 20914U 20915U 20916R 20917R 20918R 20919R 20920R 20921R 20922R 20924R 20925R 20926R 20927R 20928R 20930R 21001R 21002R 21003R/1/1 21004R 21005R 21007R 21008R 21009R 21010R 21011R 21012R 21014R 21015R 21016R 21017R/1/1 21018R 21019R 21021R 21022R 21023R 21024R 21025R 21026R/2/1 21027R 21029R/1/1 21030R 21031R 21101SH 21102SH/1/1 21103R/1/1 21107R 21108R/1/1 21109R 21110R 21111R 21112R 21113R 30110R 30111R 30112R 30113R 30114R 30115R 30116R 30118R 30119R/1/1 30120R 30121R 30122R 30123R 30124R 30126R 30127R 30128R 30129R 30130R 30131R 30202R 30203R 30204R 30205R 30206R/0/0.5 30207R 30209R 30210R 30212R 30213R 30214R 30215R 30218R 30219R 30220R 30221R 30223R 30224R 30225R/2/1 30226R 30228R 30301R 30302R 30303R 30304R 30305R 30306R 30308R 30309R/2/1 30310R 30312R 30313R 30314R 30315R 30316R 30317R 30318R 30320RH 30321R 30322R 30323R 30324R 30325R 30326R 30327R 30329R 30330R 30401R 30402RH 30403R 30405R 30406R 30407R 30409RH 30410R 30411R 30412R/1/1 30414R/1/1 30415R 30416R 30417R 30418R 30419R 30420H 30421H 30422H 30423H 30424H 30425H 30428R 30429R 30430R 30502R 30503R 30506R/1/1 30507R 30509R 30510R 30511R 30512R 30513R 30517R 30518R/0.5/1 30519R 30520R 30522R 30523R/1/1 30524R 30525R 30527RH 30528R 30529R 30601R 30602R 30603R 30604R 30605R 30608R 30609R 30610R/1/1 30611R 30612R 30617R 30618R 30619R 30620R 30622R 30623R 30624R 30627R 30630R 30701R 30702R 30703R 30706R 30707R 30708R 30709R 30710R 30711R 30712R 30714R 30715R 30716R/1/1 30717R 30720R 30721R 30722R 30723R 30724R 30727R/1/1 30728R 30729R 30730R 30731H 30801R 30803R 30804R 30805R 30806R 30807R 30809R 30810R 30811R/1/1 30812R 30813R/0.5/1 30814R 30815R 30816R 30818H 30819H 30820R 30821RH 30822R 30823R 30824R 30826R 30827R 30828R 30829R 30830R 30831RH 30901R 30904R 30905R 30906R 30907R 30909H 30910R 30911R 30912R 30914R 30915H 30916H 30917H 30918R 30919R 30921R 30922R 30923R 30924R 30925R 30926R 30927H 30928H 30929R 30930R 31001R 31002R 31003H 31004R 31005R/0/0.5 31006R 31007R 31008R 31009R 31011R 31012R 31013R 31014R 31015R 31016H 31017H 31018R 31019R 31020R/1/1 31021R 31022R 31023R 31024R 31027R 31028R 31029R 31031R 31101SH/1/1 31102SH/0/0.5 31103R 31104R 31105R 31106R 31107R 31109R 31110R 31111R 31112R 31113R 41106R 41107R 41109R 41110R 41111R 41112R', ' ')) AS r
), parsed AS (
  SELECT (ARRAY['ff481ff3-54d3-4b11-88f1-d7a7b9079a4a', 'b403b39a-07df-4748-bc64-3d2c997930f0',
                '3ac30508-e442-46c3-b7fa-b134e32241ea', '43ae55f6-fe46-46d3-8652-b1424dc03d52'])[substr(r, 1, 1)::int] AS employee_id,
         to_date('2026' || substr(r, 2, 4), 'YYYYMMDD') AS date,
         CASE split_part(substr(r, 6), '/', 1)
           WHEN 'R' THEN 'Regular' WHEN 'H' THEN 'Holiday' WHEN 'S' THEN 'Sick' WHEN 'U' THEN 'Unpaid Leave'
           WHEN 'RH' THEN 'Regular Holiday' WHEN 'SH' THEN 'Special Holiday' END AS day_type,
         coalesce(nullif(split_part(r, '/', 2), '')::numeric, 0) AS overtime_hours,
         coalesce(nullif(split_part(r, '/', 3), '')::numeric, 1) AS day_fraction
  FROM raw
)
INSERT INTO timesheets (id, employee_id, name, date, day_type, regular_hours, overtime_hours, day_fraction, payroll_status, store_id, daily_notes)
SELECT gen_random_uuid()::text, p.employee_id, e.full_name, p.date, p.day_type,
       CASE WHEN p.day_type IN ('Holiday', 'Sick') THEN 8 WHEN p.day_type = 'Unpaid Leave' THEN 0 ELSE 8 * p.day_fraction END,
       p.overtime_hours, p.day_fraction,
       CASE WHEN p.date <= DATE '2026-10-31' THEN 'Paid' ELSE 'Approved' END,
       'store-lolas', 'Imported from Staff Record Keeping sheet'
FROM parsed p JOIN employees e ON e.id = p.employee_id;

-- November 9pm returns already paid from the till: record them on the day and link the till expense,
-- so payslips show the return and deduct it as paid in cash.
UPDATE timesheets t SET nine_pm_returns_count = 1
FROM expenses x
WHERE x.id IN ('1b663a87-1b61-465c-a741-34e0478bd41a', 'bf7bc60f-f75d-4700-b03d-989c0bf7a750', 'b7d7cd6b-3b49-4d8a-bcc7-d48b561f9b6e',
               'd6dee5f1-c381-4da3-9395-5657d54d33eb', '9bb58b7f-dd80-4765-82fa-19dc63fe5103')
  AND t.employee_id = x.employee_id AND t.date = x.date;

UPDATE expenses x SET timesheet_id = t.id
FROM timesheets t
WHERE x.id IN ('1b663a87-1b61-465c-a741-34e0478bd41a', 'bf7bc60f-f75d-4700-b03d-989c0bf7a750', 'b7d7cd6b-3b49-4d8a-bcc7-d48b561f9b6e',
               'd6dee5f1-c381-4da3-9395-5657d54d33eb', '9bb58b7f-dd80-4765-82fa-19dc63fe5103')
  AND t.employee_id = x.employee_id AND t.date = x.date;